// МИНИМАЛЬНЫЙ event-driven бандл — фикстура ГЕЙТА ПРОВОДКИ, а не рабочая стратегия.
//
// Тело здесь никогда не исполняется: допуск отвергает event_driven до создания актора и до init.
// Модуль всё равно написан по контракту (`createActor` -> актор с `onEvent`), а не заглушкой из
// пустого объекта: фикстура, не соответствующая объявленной форме, доказывала бы отказ на манифесте,
// которого в проде не бывает, и перестала бы годиться в тот день, когда допуск начнёт пропускать.

export const manifest = {
  "id": "event_driven_probe",
  "version": "1.0.0",
  "kind": "strategy",
  "name": "event-driven wiring probe",
  "summary": "минимальный event_driven бандл для гейта проводки флага раскатки",
  "rationale": "доказать, что решение о допуске одинаково на прямой и потоковой дорогах",
  "author": "agent",
  "contractVersion": "017.4",
  "status": "research_only",
  "paramsSchema": {
    "type": "object",
    "additionalProperties": false,
    "properties": {}
  },
  "params": {},
  "capabilities": {
    "platformSdk": true
  },
  "dataNeeds": {
    "closedCandlesUpToCurrent": true,
    "asOfIndicators": false
  },
  "hooks": [
    "onEvent"
  ],
  "lifecycle": "event_driven",
  "marketData": [
    {
      "kind": "candles",
      "id": "req-candles",
      "instrument": {
        "venue": "binance",
        "symbol": "BTCUSDT"
      },
      "interval": 60000000,
      "lookback": 5,
      "revisionPolicy": {
        "mode": "final_only"
      },
      "priceType": "trade"
    }
  ],
  "bundleContractVersion": "019.1"
};

export function createActor(init) {
  let seen = 0;
  return {
    onEvent(_event, _ctx) {
      seen += 1;
      // Ни одной команды: гейт проводки смотрит на ОТКАЗ, а не на поведение стратегии.
      return [];
    },
    snapshot() {
      return { seen };
    },
  };
}
